for locale,mapping in (('mgo',swahili),('mni',bengali),('mzn',persian),('naq',swahili)):
    output={'@@locale':locale}
    for key,value in source.items():
        if key=='@@locale' or key.startswith('@'): continue
        output[key]=mapping.get(key,value)
    dest=root/f'lib/l10n/app_{locale}.arb'
    dest.write_text(json.dumps(output,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(locale,'wrote',len(output)-1,'messages')
